source='''def transform(grid):
    from collections import Counter
    out = [row[:] for row in grid]
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    points = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v != background]
    if not points:
        return out
    r0 = min(r for r, c in points)
    r1 = max(r for r, c in points)
    c0 = min(c for r, c in points)
    c1 = max(c for r, c in points)
    # Mark missing cells on the outer bounding-box edge.
    for r in range(r0, r1 + 1):
        for c in range(c0, c1 + 1):
            if (r == r0 or r == r1 or c == c0 or c == c1) and grid[r][c] == background:
                out[r][c] = 2
    # Also bridge gaps on any row or column containing at least three object cells.
    for r, row in enumerate(grid):
        cols = [c for c, v in enumerate(row) if v != background]
        if len(cols) >= 3:
            for c in range(min(cols), max(cols) + 1):
                if grid[r][c] == background:
                    out[r][c] = 2
    for c in range(len(grid[0])):
        rows = [r for r in range(len(grid)) if grid[r][c] != background]
        if len(rows) >= 3:
            for r in range(min(rows), max(rows) + 1):
                if grid[r][c] == background:
                    out[r][c] = 2
    return out
'''
